css:
.gp-sheet { font-family: -apple-system, "Segoe UI", Roboto, sans-serif; color: #1a1a1a; }
.gp-head { display: flex; justify-content: space-between; align-items: flex-start;
           border-bottom: 2px solid #1a1a1a; padding-bottom: 8px; margin-bottom: 10px; }
.gp-title { font-size: 20px; font-weight: 700; letter-spacing: .5px; margin: 0; }
.gp-sub { font-size: 11px; color: #555; margin-top: 2px; }
.gp-dir { font-size: 22px; font-weight: 700; border: 2px solid #1a1a1a;
          padding: 2px 14px; border-radius: 4px; }
.gp-qr { text-align: center; }
.gp-qr img { width: 92px; height: 92px; }
.gp-qr div { font-family: monospace; font-size: 10px; margin-top: 2px; }
.gp-grid { display: flex; flex-wrap: wrap; margin: 0 -6px 10px; }
.gp-cell { flex: 1 1 33%; padding: 3px 6px; box-sizing: border-box; }
.gp-cell .k { font-size: 9px; text-transform: uppercase; letter-spacing: .4px; color: #777; }
.gp-cell .v { font-size: 12px; font-weight: 600; }
table.gp-items { width: 100%; border-collapse: collapse; margin-bottom: 10px; }
table.gp-items th { background: #f1f1f1; border: 1px solid #bbb; padding: 4px 6px;
                    font-size: 10px; text-transform: uppercase; text-align: left; }
table.gp-items td { border: 1px solid #ccc; padding: 4px 6px; font-size: 11px; }
table.gp-items td.num, table.gp-items th.num { text-align: right; }
.gp-note { border-left: 3px solid #888; background: #fafafa; padding: 6px 10px;
           font-size: 11px; margin-bottom: 10px; }
.gp-bad { border-left-color: #c0392b; background: #fdf3f2; }
.gp-sign { display: flex; justify-content: space-between; margin-top: 26px; }
.gp-sign div { flex: 1; text-align: center; font-size: 10px; color: #555;
               border-top: 1px solid #999; margin: 0 10px; padding-top: 4px; }
.gp-foot { margin-top: 12px; font-size: 9px; color: #888; text-align: center; }

html:
{%- macro cell(k, v) %}{% if v %}<div class="gp-cell"><div class="k">{{ k }}</div>
<div class="v">{{ v }}</div></div>{% endif %}{% endmacro %}
<div class="gp-sheet">

<div class="gp-head">
  <div>
    <p class="gp-title">{{ _("GATE PASS — DETAIL") }}</p>
    <div class="gp-sub">{{ doc.company }}{% if doc.location %} &middot; {{ doc.location }}{% endif %}
      {%- if doc.gate %} &middot; {{ _("Gate") }} {{ doc.gate }}{% endif %}</div>
  </div>
  <div style="text-align:center">
    <div class="gp-dir">{{ _(doc.direction)|upper }}</div>
    <div class="gp-sub">{{ doc.name }}</div>
  </div>
  <div class="gp-qr">
    {%- set qr = get_qr_code(doc.name) %}
    {%- if qr %}<img src="{{ qr }}">{% endif %}
    <div>{{ doc.name }}</div>
  </div>
</div>


<div class="gp-grid">
  {{ cell(_("Date"), frappe.format(doc.posting_date, {"fieldtype":"Date"})) }}
  {{ cell(_("Time"), frappe.format(doc.posting_time, {"fieldtype":"Time"})) }}
  {{ cell(_(doc.party_type or "Party"), doc.party_name or doc.party or doc.party_display_name) }}
  {{ cell(_("Vehicle"), doc.vehicle_number) }}
  {{ cell(_("Driver"), doc.driver_name) }}
  {{ cell(_("Driver Contact"), doc.driver_contact) }}
  {{ cell(_("Transporter"), doc.transporter) }}
  {{ cell(_("LR / Consignment"), doc.lr_number) }}
  {{ cell(_("Invoice / Challan"), doc.reference_no) }}
  {{ cell(_("Source"), doc.source_document) }}
  {{ cell(_("Purpose"), doc.purpose) }}
  {{ cell(_("Security Officer"), doc.security_officer_name or doc.security_officer) }}
</div>

<div class="gp-grid">
  {{ cell(_("Status"), _(doc.status)) }}
  {{ cell(_("Entry"), frappe.format(doc.entry_datetime, {"fieldtype":"Datetime"})) }}
  {{ cell(_("Exit"), frappe.format(doc.exit_datetime, {"fieldtype":"Datetime"})) }}
  {{ cell(_("Tracking ID"), doc.tracking_id) }}
  {{ cell(_("Net Weight"), doc.net_weight) }}
  {{ cell(_("Packages"), doc.total_packages) }}
</div>

{%- set checks = get_compliance_summary(doc.name) %}
{%- if checks %}
<div class="gp-note">
  <b>{{ _("Statutory") }}:</b>
  {%- for c in checks %} {{ c.label }}: <b>{{ c.document_no or _(c.status) }}</b>{% if not loop.last %} &middot;{% endif %}{% endfor %}
</div>
{%- endif %}

{%- set show_discrepancy = true %}

<table class="gp-items">
  <thead><tr>
    <th style="width:28px">#</th><th>{{ _("Item") }}</th><th>{{ _("Description") }}</th>
    <th class="num">{{ _("Qty") }}</th><th style="width:48px">{{ _("UOM") }}</th>
    {%- if show_discrepancy %}<th class="num">{{ _("Accepted") }}</th><th class="num">{{ _("Short") }}</th>
    <th class="num">{{ _("Damaged") }}</th>{% endif %}
  </tr></thead>
  <tbody>
  {%- for r in doc.items %}
    <tr>
      <td>{{ loop.index }}</td>
      <td>{{ r.item_code or "" }}</td>
      <td>{{ r.item_name or "" }}</td>
      <td class="num">{{ frappe.format(r.qty, {"fieldtype":"Float"}) }}</td>
      <td>{{ r.uom or "" }}</td>
      {%- if show_discrepancy %}
      <td class="num">{{ frappe.format(r.accepted_qty, {"fieldtype":"Float"}) }}</td>
      <td class="num">{{ frappe.format(r.shortage_qty, {"fieldtype":"Float"}) if r.shortage_qty else "" }}</td>
      <td class="num">{{ frappe.format(r.damaged_qty, {"fieldtype":"Float"}) if r.damaged_qty else "" }}</td>
      {%- endif %}
    </tr>
  {%- endfor %}
  </tbody>
  <tfoot><tr>
    <th colspan="3" style="text-align:right">{{ _("Total") }}</th>
    <th class="num">{{ frappe.format(doc.total_qty, {"fieldtype":"Float"}) }}</th><th></th>
    {%- if show_discrepancy %}<th class="num">{{ frappe.format(doc.total_accepted_qty, {"fieldtype":"Float"}) }}</th>
    <th class="num">{{ frappe.format(doc.total_shortage_qty, {"fieldtype":"Float"}) }}</th>
    <th class="num">{{ frappe.format(doc.total_damaged_qty, {"fieldtype":"Float"}) }}</th>{% endif %}
  </tr></tfoot>
</table>

{%- if doc.has_discrepancy %}
<div class="gp-note gp-bad"><b>{{ _("Discrepancy") }}:</b> {{ doc.discrepancy_notes or "" }}</div>
{%- endif %}
{%- if doc.charges %}
<table class="gp-items"><thead><tr><th>{{ _("Charge") }}</th>
  <th class="num">{{ _("Amount") }}</th><th>{{ _("Paid By") }}</th></tr></thead><tbody>
{%- for c in doc.charges %}<tr><td>{{ c.charge_type }}</td>
  <td class="num">{{ frappe.format(c.amount, {"fieldtype":"Currency"}) }}</td>
  <td>{{ _(c.paid_by or "") }}</td></tr>{% endfor %}
</tbody></table>
{%- endif %}
{%- if doc.remarks %}<div class="gp-note">{{ doc.remarks }}</div>{% endif %}

<div class="gp-sign">
  <div>{{ _("Security Officer") }}</div>
  <div>{{ _("Driver") }}</div>
  <div>{{ _("Authorised By") }}</div>
</div>
<div class="gp-foot">{{ doc.name }} &middot; {{ _("printed") }}
  {{ frappe.format(frappe.utils.now(), {"fieldtype":"Datetime"}) }}</div>

</div>
